import os
import torch


class CFG:
    # ====================================================
    # General Settings
    # ====================================================
    seed = 42
    debug = False  # Set to True to run with a small subset of data for debugging
    num_workers = 4
    print_freq = 100
    verbose = True

    # ====================================================
    # Paths
    # ====================================================
    # Metadata paths (generated by the provided script)
    train_path = "./metadata/train.csv"
    val_path = "./metadata/val.csv"
    test_path = "./metadata/test.csv"
    sample_submission_path = "./input/sample_submission.csv"

    # Working directory for outputs and temporary files
    output_dir = "./working/idea_9"
    if not os.path.exists(output_dir):
        os.makedirs(output_dir, exist_ok=True)

    # Paths for cached processed data
    cpc_text_path = os.path.join(output_dir, "cpc_texts.parquet")
    train_processed_path = os.path.join(output_dir, "train_processed.parquet")
    val_processed_path = os.path.join(output_dir, "val_processed.parquet")
    test_processed_path = os.path.join(output_dir, "test_processed.parquet")

    # Directory to save model checkpoints
    model_dir = os.path.join(output_dir, "models")
    if not os.path.exists(model_dir):
        os.makedirs(model_dir, exist_ok=True)

    # Submission file
    submission_path = "./submission/submission.csv"
    os.makedirs(os.path.dirname(submission_path), exist_ok=True)

    # ====================================================
    # Model Architecture
    # ====================================================
    model_name = "microsoft/deberta-v3-large"
    gradient_checkpointing = True

    # Pooling Strategy: 'mean', 'max', 'attention', 'cls'
    pooling = "attention"

    # Input Tokenization
    max_len = 130  # Sufficient for Anchor + Target + Context Description

    # Internal Feature Fusion
    # We concatenate these structural features before the classification head
    # 1. Normalized Levenshtein Distance
    # 2. Jaccard Similarity
    # 3. Length Ratio
    num_structural_features = 3

    # Classification Head
    # We treat the regression problem as a classification over the 5 discrete scores
    # Classes: {0.0, 0.25, 0.5, 0.75, 1.0}
    num_classes = 5
    fc_dropout = 0.2

    # ====================================================
    # Training Parameters
    # ====================================================
    epochs = 5

    # Batch Size Configuration for A100 (40GB)
    # Effective Batch Size = batch_size * gradient_accumulation_steps
    # Target Effective BS = 32
    batch_size = 8
    gradient_accumulation_steps = 4

    # Gradient Clipping
    max_grad_norm = 1.0

    # Optimizer (AdamW)
    encoder_lr = 2e-5
    head_lr = 1e-4
    weight_decay = 0.01
    eps = 1e-6
    betas = (0.9, 0.999)

    # Scheduler (Cosine with Warmup)
    scheduler = "cosine"
    warmup_ratio = 0.1
    num_cycles = 0.5

    # Loss Function
    label_smoothing = 0.1

    # ====================================================
    # Adversarial Weight Perturbation (AWP)
    # ====================================================
    use_awp = True
    awp_lr = 1e-4
    awp_eps = 1e-2
    # Start AWP after the first epoch (index 1) to allow initial convergence
    awp_start_epoch = 1.0

    # ====================================================
    # Stacking / Cross-Validation
    # ====================================================
    n_fold = 5
    target_col = "score"

    # ====================================================
    # Device
    # ====================================================
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
